-- Milestone 1 schema. Apply with `supabase db reset` locally.
create extension if not exists pgcrypto;
create type public.profile_role as enum ('admin', 'agent');
create type public.property_status as enum ('draft', 'published', 'archived');
create type public.property_type as enum ('house', 'apartment', 'townhouse', 'land', 'commercial');
create type public.listing_type as enum ('sale', 'rent');
create type public.enquiry_status as enum ('new', 'contacted', 'qualified', 'closed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null unique, phone text, avatar_url text, role public.profile_role not null default 'agent', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.properties (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null check(length(title) between 3 and 180), description text not null check(length(description)>=20), excerpt text, property_type public.property_type not null, listing_type public.listing_type not null, status public.property_status not null default 'draft', price numeric(14,2) not null check(price>=0), currency text not null default 'USD', address_line_1 text not null, address_line_2 text, city text not null, region text not null, postal_code text, country text not null default 'US', latitude numeric, longitude numeric, bedrooms integer not null default 0 check(bedrooms>=0), bathrooms integer not null default 0 check(bathrooms>=0), parking_spaces integer not null default 0 check(parking_spaces>=0), floor_area numeric check(floor_area>=0), lot_size numeric check(lot_size>=0), year_built integer, featured boolean not null default false, amenities text[] not null default '{}', agent_id uuid references public.profiles(id) on delete set null, created_by uuid references public.profiles(id) on delete set null, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.property_images (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, storage_path text not null unique, alt_text text, sort_order integer not null default 0, is_primary boolean not null default false, width integer, height integer, created_at timestamptz not null default now());
create unique index one_primary_image_per_property on public.property_images(property_id) where is_primary;
create table public.enquiries (id uuid primary key default gen_random_uuid(), property_id uuid references public.properties(id) on delete set null, name text not null check(length(name)>=2), email text not null check(position('@' in email)>1), phone text, message text not null check(length(message)>=5), status public.enquiry_status not null default 'new', assigned_to uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index properties_public_search on public.properties(status,city,property_type,listing_type,price,bedrooms,featured,created_at desc); create index property_images_property on public.property_images(property_id,sort_order);
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and active)$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin' and active)$$;
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.property_images enable row level security; alter table public.enquiries enable row level security;
create policy "staff read profiles" on public.profiles for select to authenticated using(public.is_staff());
create policy "public published properties" on public.properties for select to anon,authenticated using(status='published' or public.is_staff());
create policy "staff create properties" on public.properties for insert to authenticated with check(public.is_staff() and (public.is_admin() or created_by=auth.uid()));
create policy "staff update properties" on public.properties for update to authenticated using(public.is_admin() or agent_id=auth.uid() or created_by=auth.uid()) with check(public.is_admin() or agent_id=auth.uid() or created_by=auth.uid());
create policy "admin delete properties" on public.properties for delete to authenticated using(public.is_admin());
create policy "public read images" on public.property_images for select to anon,authenticated using(exists(select 1 from properties p where p.id=property_id and (p.status='published' or public.is_staff())));
create policy "staff manage images" on public.property_images for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "public create enquiry" on public.enquiries for insert to anon,authenticated with check(property_id is null or exists(select 1 from properties where id=property_id and status='published'));
create policy "staff manage enquiries" on public.enquiries for select to authenticated using(public.is_staff()); create policy "staff update enquiries" on public.enquiries for update to authenticated using(public.is_staff()) with check(public.is_staff());
create or replace function public.search_properties(p_query text default null,p_listing_type public.listing_type default null,p_property_type public.property_type default null,p_city text default null,p_min_price numeric default null,p_max_price numeric default null,p_min_bedrooms integer default null,p_min_bathrooms integer default null,p_featured boolean default null,p_page integer default 1,p_page_size integer default 12) returns table(id uuid,slug text,title text,excerpt text,property_type public.property_type,listing_type public.listing_type,price numeric,currency text,city text,region text,bedrooms integer,bathrooms integer,parking_spaces integer,floor_area numeric,featured boolean,published_at timestamptz,primary_image_path text,primary_image_alt text,total_count bigint) language sql stable security invoker as $$ with filtered as (select p.*,count(*) over() total_count from properties p where p.status='published' and (p_query is null or p.title ilike '%'||p_query||'%' or p.city ilike '%'||p_query||'%') and (p_listing_type is null or p.listing_type=p_listing_type) and (p_property_type is null or p.property_type=p_property_type) and (p_city is null or p.city ilike '%'||p_city||'%') and (p_min_price is null or p.price>=p_min_price) and (p_max_price is null or p.price<=p_max_price) and (p_min_bedrooms is null or p.bedrooms>=p_min_bedrooms) and (p_min_bathrooms is null or p.bathrooms>=p_min_bathrooms) and (p_featured is null or p.featured=p_featured)) select f.id,f.slug,f.title,f.excerpt,f.property_type,f.listing_type,f.price,f.currency,f.city,f.region,f.bedrooms,f.bathrooms,f.parking_spaces,f.floor_area,f.featured,f.published_at,i.storage_path,i.alt_text,f.total_count from filtered f left join property_images i on i.property_id=f.id and i.is_primary order by f.featured desc,f.published_at desc nulls last offset greatest(p_page-1,0)*greatest(p_page_size,1) limit greatest(p_page_size,1); $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('property-images','property-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "staff upload property images" on storage.objects for insert to authenticated with check(bucket_id='property-images' and public.is_staff()); create policy "staff delete property images" on storage.objects for delete to authenticated using(bucket_id='property-images' and public.is_staff());

create or replace function public.publish_property(p_property_id uuid) returns public.properties language plpgsql security invoker as $$ declare result public.properties; begin update properties set status='published',published_at=coalesce(published_at,now()),updated_at=now() where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid()) returning * into result; if result.id is null then raise exception 'Property not found or access denied'; end if; return result; end $$;
create or replace function public.archive_property(p_property_id uuid) returns public.properties language plpgsql security invoker as $$ declare result public.properties; begin update properties set status='archived',updated_at=now() where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid()) returning * into result; if result.id is null then raise exception 'Property not found or access denied'; end if; return result; end $$;
create or replace function public.restore_property(p_property_id uuid) returns public.properties language plpgsql security invoker as $$ declare result public.properties; begin update properties set status='draft',updated_at=now() where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid()) returning * into result; if result.id is null then raise exception 'Property not found or access denied'; end if; return result; end $$;
create or replace function public.reserve_property_image(p_property_id uuid,p_filename text,p_content_type text) returns jsonb language plpgsql security invoker as $$ declare image_id uuid:=gen_random_uuid(); image_path text; begin if not exists(select 1 from properties where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid())) then raise exception 'Access denied'; end if; image_path:=p_property_id::text||'/'||image_id::text||'.'||coalesce(nullif(regexp_replace(lower(p_filename),'^.*\\.','','g'),''),'jpg'); insert into property_images(id,property_id,storage_path,alt_text,sort_order) values(image_id,p_property_id,image_path,regexp_replace(p_filename,'\\.[^.]+$',''),(select coalesce(max(sort_order),-1)+1 from property_images where property_id=p_property_id)); return jsonb_build_object('image_id',image_id,'storage_path',image_path); end $$;
create or replace function public.set_primary_property_image(p_property_id uuid,p_image_id uuid) returns void language plpgsql security invoker as $$ begin if not exists(select 1 from properties where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid())) then raise exception 'Access denied'; end if; update property_images set is_primary=false where property_id=p_property_id; update property_images set is_primary=true where id=p_image_id and property_id=p_property_id; if not found then raise exception 'Image not found'; end if; end $$;
create or replace function public.reorder_property_images(p_property_id uuid,p_image_ids uuid[]) returns void language plpgsql security invoker as $$ begin if not exists(select 1 from properties where id=p_property_id and (public.is_admin() or agent_id=auth.uid() or created_by=auth.uid())) then raise exception 'Access denied'; end if; update property_images i set sort_order=s.ordinality-1 from unnest(p_image_ids) with ordinality as s(id,ordinality) where i.id=s.id and i.property_id=p_property_id; end $$;
